package main

import (
	"context"
	"encoding/json"
	"log/slog"
	"math"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/mellifera/mellifera/internal/plugin"
	"github.com/mellifera/mellifera/internal/store"
	"github.com/mellifera/mellifera/pkg/sdk"
	metadatav1 "github.com/mellifera/mellifera/proto/mellifera/metadata/v1"
	scannerv1 "github.com/mellifera/mellifera/proto/mellifera/scanner/v1"
	"google.golang.org/protobuf/types/known/structpb"
)

// Lifecycle knobs for the stop-frame re-grab executor (continue-nextup-media
// D-2/D-3): a re-grab is accepted only when the incoming position moved
// ≥ regrabDebounce past the item's last grabbed position (the player flushes
// progress every few seconds of playhead drift), and each accepted grab runs
// under a regrabTimeout budget — ffmpeg outlives the HTTP request that
// triggered it, but never the process.
const (
	regrabDebounce = 60 * time.Second
	regrabTimeout  = 60 * time.Second
)

// thumbStore is the store seam the re-grab executor reads through (the one
// store.GetItem caller shape it needs). *store.Store satisfies it; tests
// inject a fake. Keeping the seam narrow mirrors enrich.metadataResolver —
// the executor can never grow a document write because the seam has none
// (D-1: the JPEG overwrites the deterministic path, the document stays put).
type thumbStore interface {
	GetItem(ctx context.Context, id string) (store.Item, error)
}

// thumbSources is the plugin seam (plugin.Manager.MetadataSource's shape).
// *plugin.Manager satisfies it; tests inject a fake that returns an error to
// exercise the plugin-unavailable path.
type thumbSources interface {
	MetadataSource(pluginID, capabilityID string) (sdk.MetadataSource, error)
}

// thumbRegrabber is the debounced stop-frame re-grab executor behind
// Deps.OnProgress (continue-nextup-media D-2/D-3/D-4). Per item it remembers
// the LAST GRABBED position (updated only on acceptance — a stream of
// creeping 5-second writes must never walk its way into a re-grab) and
// accepts a re-grab only when |newPos − lastPos| ≥ debounce. The map is
// bounded by distinct played items (dev-scale fine; a real LRU is deferred).
// Every failure is log-and-skip: a progress write is never load-bearing, no
// failure reaches the PUT response, and the stored document is never written.
type thumbRegrabber struct {
	store    thumbStore
	sources  thumbSources
	debounce time.Duration
	timeout  time.Duration

	mu      sync.Mutex
	lastPos map[string]float64
}

// newThumbRegrab builds the Deps.OnProgress closure over the real store and
// plugin manager — the composition root's one wiring point (main.go, beside
// the Play closure). The returned closure never blocks the PUT longer than
// the debounce check and never returns an error.
func newThumbRegrab(st *store.Store, mgr *plugin.Manager) func(ctx context.Context, itemID string, position int64) {
	r := &thumbRegrabber{
		store:    st,
		sources:  mgr,
		debounce: regrabDebounce,
		timeout:  regrabTimeout,
		lastPos:  make(map[string]float64),
	}
	return r.onProgress
}

// onProgress is the api Deps.OnProgress seam: debounce synchronously (so
// concurrent writes for one item cannot double-grab), then run the grab
// DETACHED from the request context — context.WithoutCancel, because the
// request ctx dies with the response while the ffmpeg grab outlives it (D-2).
// The process-level shutdown still reaps it via the regrabTimeout budget.
func (r *thumbRegrabber) onProgress(ctx context.Context, itemID string, position int64) {
	pos := float64(position)
	r.mu.Lock()
	if last, ok := r.lastPos[itemID]; ok && math.Abs(pos-last) < r.debounce.Seconds() {
		r.mu.Unlock()
		return
	}
	r.lastPos[itemID] = pos
	r.mu.Unlock()
	go r.regrab(context.WithoutCancel(ctx), itemID, pos)
}

// regrab is the accepted re-grab flow: stored document → frame-grabber Match
// → inject seek_seconds = the saved position → Convert (D-4). The plugin is
// the single ffmpeg exec site; the core never grows one. Every failure path
// logs and returns — the JPEG lands on the same deterministic path (D-1) or
// not at all, and grabbed_at stays stale by design.
func (r *thumbRegrabber) regrab(ctx context.Context, itemID string, position float64) {
	ctx, cancel := context.WithTimeout(ctx, r.timeout)
	defer cancel()

	row, err := r.store.GetItem(ctx, itemID)
	if err != nil {
		slog.Warn("thumb re-grab: item lookup failed", "item", itemID, "error", err)
		return
	}
	var doc map[string]any
	if err := json.Unmarshal(row.Document, &doc); err != nil {
		slog.Warn("thumb re-grab: stored document unreadable", "item", itemID, "error", err)
		return
	}
	src, err := r.sources.MetadataSource("frame-grabber", "default")
	if err != nil {
		slog.Warn("thumb re-grab: frame-grabber unavailable", "item", itemID, "error", err)
		return
	}
	match, err := src.Match(ctx, &metadatav1.MatchRequest{Item: thumbBase(doc), ModuleType: row.MediaType})
	if err != nil {
		slog.Warn("thumb re-grab: match failed", "item", itemID, "error", err)
		return
	}
	if !match.GetApplies() {
		slog.Info("thumb re-grab: match declined", "item", itemID, "reason", match.GetReason())
		return
	}
	q := match.GetQuery()
	if q == nil {
		q = &structpb.Struct{}
	}
	if q.Fields == nil {
		q.Fields = make(map[string]*structpb.Value, 1)
	}
	// The stop position IS the seek: Convert clamps it against the
	// probe-reported duration (a bogus position cannot seek past EOF).
	q.Fields["seek_seconds"] = structpb.NewNumberValue(position)
	conv, err := src.Convert(ctx, &metadatav1.ConvertRequest{Query: q, ModuleType: row.MediaType})
	if err != nil {
		slog.Warn("thumb re-grab: convert failed", "item", itemID, "error", err)
		return
	}
	if warns := conv.GetWarnings(); len(warns) > 0 {
		// The plugin's soft-fail path (ffmpeg missing/non-zero/timeout): the
		// old bytes stay served, which is exactly the log-and-skip posture.
		slog.Warn("thumb re-grab: convert soft-failed", "item", itemID, "warnings", strings.Join(warns, "; "))
		return
	}
	slog.Info("thumb re-grab: refreshed stop frame", "item", itemID, "position_seconds", position)
}

// thumbBase rebuilds the per-item *scannerv1.IdentifyResult the plugin's Match
// consumes FROM THE STORED DOCUMENT — the same reconstruction the enrich
// worker does (parsed Struct out of doc["parsed"], the probe-reported duration
// surfaced as the well-known probe_duration_seconds parsed fact). A
// missing/unparseable parsed or probe simply leaves the fact absent; Match
// then decides applicability from whatever parsed facts remain.
func thumbBase(doc map[string]any) *scannerv1.IdentifyResult {
	st := &structpb.Struct{}
	if parsed, ok := doc["parsed"].(map[string]any); ok {
		if s, err := structpb.NewStruct(parsed); err == nil {
			st = s
		}
	}
	if d, ok := thumbProbeDuration(doc["ffprobe"]); ok {
		if st.Fields == nil {
			st.Fields = make(map[string]*structpb.Value, 1)
		}
		st.Fields["probe_duration_seconds"] = structpb.NewNumberValue(d)
	}
	return &scannerv1.IdentifyResult{Parsed: st}
}

// thumbProbeDuration extracts the probe-reported duration in seconds from the
// document's ffprobe namespace ({"format": {"duration": "<seconds>"}} —
// verbatim ffprobe output carries it as a JSON string; a store round-trip
// decodes the document to maps, so that is the only shape read here).
func thumbProbeDuration(raw any) (float64, bool) {
	m, ok := raw.(map[string]any)
	if !ok {
		return 0, false
	}
	format, ok := m["format"].(map[string]any)
	if !ok {
		return 0, false
	}
	switch d := format["duration"].(type) {
	case string:
		n, err := strconv.ParseFloat(d, 64)
		if err != nil || n <= 0 {
			return 0, false
		}
		return n, true
	case float64:
		if d <= 0 {
			return 0, false
		}
		return d, true
	default:
		return 0, false
	}
}
